func ValsSelfObject(keyTokens [][]byte, indices []int, vals Vals, out []byte) []byte {
	out = append(out, '{')

	first := true

	for i, idx := range indices {
		v := vals[idx]
		if len(v) == 0 {
			continue // MISSING field -> omit key (matches Convert's UnsetField).
		}

		if !first {
			out = append(out, ',')
		}
		first = false

		out = append(out, keyTokens[i]...)
		if v[0] == SigilVariant {
			// A VARIANT carrier can't be spliced as raw bytes into JSON; project it.
			out = VariantProjectJSON(out, v)
		} else {
			out = append(out, v...)
		}
	}

	out = append(out, '}')

	return out
}
